import{Game,WEAPONS,wrap}from'./engine.js';import{Renderer}from'./render.js';
const $=s=>document.querySelector(s),canvas=$('#game'),renderer=new Renderer(canvas),keys=new Set();let game=new Game(),muted=false,audio=null,master=null,last=performance.now(),msgTime=0,pointer=false,drag=null,mouseFire=false,touchInput={forward:0,strafe:0,fire:false},overlayStatus='title',manualUntil=0,beat=0,sfxCooldown=0,lastRenderStatus=null,hudTimer=0;game.status='title';
function audioStart(){try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=.22;master.connect(audio.destination)}if(audio.state==='suspended')audio.resume().catch(()=>{})}catch{}}
function tone(freq,duration,type='sawtooth',volume=.14,to=null){if(!audio||muted)return;let t=audio.currentTime,o=audio.createOscillator(),v=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(to)o.frequency.exponentialRampToValueAtTime(Math.max(20,to),t+duration);v.gain.setValueAtTime(volume,t);v.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(v);v.connect(master);o.start(t);o.stop(t+duration)}
function noise(duration=.12,volume=.2){if(!audio||muted)return;let b=audio.createBuffer(1,audio.sampleRate*duration,audio.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);let n=audio.createBufferSource(),f=audio.createBiquadFilter(),v=audio.createGain();f.type='lowpass';f.frequency.value=1600;v.gain.value=volume;n.buffer=b;n.connect(f);f.connect(v);v.connect(master);n.start()}
function sound(type,e){if(type==='shoot'){noise(e.weapon===1?.24:.1,e.weapon===1?.6:.25);tone(e.weapon===2?220:110,.18,'sawtooth',.22,35)}else if(type==='kill'){tone(380,.23,'sawtooth',.13,90)}else if(type==='hurt'){if(performance.now()-sfxCooldown>180){tone(180,.16,'triangle',.2,70);sfxCooldown=performance.now()}}else if(type==='pickup'||type==='secret'){tone(520,.15,'square',.08,1040)}else if(type==='boom'){noise(.38,.6);tone(65,.35,'sine',.4,22)}else if(type==='enemyshot')tone(180,.12,'sawtooth',.03,340)}
const music=setInterval(()=>{if(game.status!=='playing'||muted||!audio)return;let notes=[55,55,65.4,55,49,55,73.4,65.4];tone(notes[beat%8],.16,'sawtooth',.09);if(beat%4===0)tone(90,.13,'sine',.3,32);if(beat%4===2)noise(.08,.15);beat++},230);
function message(t,seconds=3){if(!t)return;$('#message').textContent=t;msgTime=seconds}
function release(){keys.clear();mouseFire=false;touchInput={forward:0,strafe:0,fire:false};drag=null;try{if(document.pointerLockElement)document.exitPointerLock()}catch{}}
function lock(){if(matchMedia('(pointer:coarse)').matches)return;try{let req=canvas.requestPointerLock?.();req?.catch(()=>message('DRAG TO LOOK · ARROW KEYS ALSO TURN',3))}catch{message('DRAG TO LOOK · ARROW KEYS ALSO TURN',3)}}
function begin(difficulty){if(!['normal','easy','hard'].includes(difficulty))throw Error('Choose normal, easy, or hard.');game=new Game(difficulty);game.status='playing';renderer.map=false;$('#overlay').hidden=true;overlayStatus=null;audioStart();canvas.focus();message('WASD MOVE · SPACE FIRE · M MAP. GO GET DINNER.',6);processEvents();hud()}
function formatTime(t){return Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0')}
function panel(status){if(overlayStatus===status)return;overlayStatus=status;release();let title='',desc='',actions='',stats='';if(status==='paused'){title='CAT NAP.';desc='The invasion can wait a minute.';actions='<button class="primary" data-action="resume">BACK TO THE SCRATCHING</button><button data-action="restart">RESTART SECTOR</button>'}
 if(status==='dead'){title='CURIOSITY GOT YOU.';desc='Strafe to dodge fireballs. Hold fire. Your Paw Blaster has unlimited ammo.';actions='<button class="primary" data-action="restart">ANOTHER LIFE · RETRY SECTOR</button><button data-action="new">NEW CAMPAIGN</button>'}
 if(status==='intermission'){title='SECTOR SCRATCHED.';desc=game.world.joke;actions='<button class="primary" data-action="continue">ENTER NEXT SECTOR ▶</button>'}
 if(status==='won'){title='THE BOWL IS YOURS.';desc='Chairman Meow is history. The factory is yours.<br>You demand wet food. And dental.';actions='<button class="primary" data-action="new">PLAY AGAIN</button>'}
 if(status!=='paused')stats='<div class="stats"><div><b>'+game.score+'</b><small>SCORE</small></div><div><b>'+game.totalKills+'</b><small>CATS EXORCISED</small></div><div><b>'+formatTime(game.elapsed)+'</b><small>TIME</small></div></div><p class="eyebrow">'+game.totalSecrets+' SECRET STASH'+(game.totalSecrets===1?'':'ES')+' FOUND</p>';
 $('#overlay').innerHTML='<div class="panel"><p class="eyebrow">'+game.world.name+'</p><h2>'+title+'</h2><p>'+desc+'</p>'+stats+actions+'</div>';$('#overlay').hidden=false;$('#overlay').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>campaign(b.dataset.action));$('#overlay').querySelector('button')?.focus()}
function campaign(action,difficulty){if(action==='new'){begin(difficulty||game.difficulty);return}if(action==='pause'){if(game.status!=='playing')throw Error('Only a running game can be paused.');game.status='paused';panel('paused');return}if(action==='resume'){if(game.status!=='paused')throw Error('The game is not paused.');game.status='playing';$('#overlay').hidden=true;overlayStatus=null;audioStart();canvas.focus();last=performance.now();return}if(action==='restart'){if(game.status==='title')throw Error('Start a campaign first.');game.restart();$('#overlay').hidden=true;overlayStatus=null;audioStart();canvas.focus();processEvents();hud();return}if(action==='continue'){if(game.status!=='intermission')throw Error('Reach the sector exit first.');game.load(game.level+1);$('#overlay').hidden=true;overlayStatus=null;audioStart();canvas.focus();processEvents();hud();return}throw Error('Unknown campaign action.')}
function pause(){if(game.status==='playing')campaign('pause');else if(game.status==='paused')campaign('resume')}
function processEvents(){for(let e of game.events){sound(e.type,e);if(e.text)message(e.text,e.type==='sector'?5:3.5);if(e.type==='hit')renderer.hit=.12;if(['dead','won','intermission'].includes(e.type))panel(e.type)}game.events=[]}
function hud(){let p=game.player;$('#sector').textContent=game.world.name;$('#health').innerHTML=Math.ceil(p.hp)+'<span>%</span>';$('#health').style.color=p.hp<30?'#ff8a60':'#e4edbe';$('#healthMeter').style.width=p.hp+'%';$('#armor').textContent=Math.ceil(p.armor);$('#weaponName').textContent=WEAPONS[p.weapon].name;$('#ammo').textContent=p.weapon===0?'∞':p.weapon===1?p.shells:p.balls;$('#kills').innerHTML=game.kills+' <span>/ '+game.enemies.length+'</span>';$('#key').textContent=p.key?'YES':'—';$('#key').style.color=p.key?'#f8d87e':'#819579';$('#score').textContent=String(game.score).padStart(6,'0');$('#objective').textContent=game.level===2&&game.enemies.some(e=>e.type==='boss'&&e.alive)?'DEFEAT CHAIRMAN MEOW.':p.key?'FIND THE GREEN EXIT.':'FIND THE GOLD FISH KEY. M: MAP';renderer.face(game,$('#catFace'))}
$('#start').onclick=()=>{begin($('#difficulty').value);lock()};$('#pauseButton').onclick=pause;$('#mapButton').onclick=()=>{renderer.map=!renderer.map;canvas.focus()};$('#sound').onclick=()=>{muted=!muted;$('#sound').textContent=muted?'SOUND OFF':'SOUND ON';audioStart()};$('#fullButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#shell').requestFullscreen()}catch{message('Fullscreen unavailable here. Open the game in your browser for a larger view.',5)}};
addEventListener('keydown',e=>{if(e.target.tagName==='SELECT')return;if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat&&['KeyP','Escape','KeyM','KeyE','Digit1','Digit2','Digit3'].includes(e.code))return;if(e.code==='KeyP'||e.code==='Escape'){pause();return}if(game.status!=='playing')return;keys.add(e.code);if(e.code==='KeyM')renderer.map=!renderer.map;if(e.code==='KeyE')game.interact();if(/^Digit[123]$/.test(e.code))game.equip(Number(e.code.slice(-1))-1)});
addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{if(game.status==='playing')campaign('pause');release()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.status==='playing')campaign('pause')});
canvas.addEventListener('pointerdown',e=>{if(game.status!=='playing'||e.pointerType==='touch')return;audioStart();canvas.focus();if(e.button===0){mouseFire=true;drag={id:e.pointerId,x:e.clientX};canvas.setPointerCapture?.(e.pointerId);if(!document.pointerLockElement)lock()}});canvas.addEventListener('pointerup',()=>{mouseFire=false;drag=null});addEventListener('pointerup',()=>{mouseFire=false;drag=null});canvas.addEventListener('contextmenu',e=>e.preventDefault());
document.addEventListener('pointerlockchange',()=>{let was=pointer;pointer=document.pointerLockElement===canvas;if(was&&!pointer&&game.status==='playing')campaign('pause')});document.addEventListener('mousemove',e=>{if(pointer&&game.status==='playing')game.player.a=wrap(game.player.a+e.movementX*.0032)});canvas.addEventListener('pointermove',e=>{if(!pointer&&drag&&game.status==='playing'){game.player.a=wrap(game.player.a+(e.clientX-drag.x)*.005);drag.x=e.clientX}});
let stickId=null;$('#stick').onpointerdown=e=>{stickId=e.pointerId;$('#stick').setPointerCapture(e.pointerId);stick(e)};$('#stick').onpointermove=e=>{if(e.pointerId===stickId)stick(e)};function stick(e){e.preventDefault();let r=$('#stick').getBoundingClientRect(),dx=Math.max(-1,Math.min(1,(e.clientX-r.x-r.width/2)/38)),dy=Math.max(-1,Math.min(1,(e.clientY-r.y-r.height/2)/38));touchInput.strafe=dx;touchInput.forward=-dy;$('#stick i').style.transform='translate('+dx*28+'px,'+dy*28+'px)'}for(let type of['pointerup','pointercancel','lostpointercapture'])$('#stick').addEventListener(type,()=>{stickId=null;touchInput.forward=touchInput.strafe=0;$('#stick i').style.transform=''});
let look=null;$('#lookZone').onpointerdown=e=>{look={id:e.pointerId,x:e.clientX};e.target.setPointerCapture(e.pointerId)};$('#lookZone').onpointermove=e=>{if(look&&look.id===e.pointerId&&game.status==='playing'){game.player.a=wrap(game.player.a+(e.clientX-look.x)*.008);look.x=e.clientX}};$('#lookZone').onpointerup=()=>look=null;$('#lookZone').onpointercancel=()=>look=null;
$('#touchFire').onpointerdown=e=>{e.preventDefault();audioStart();touchInput.fire=true;e.target.setPointerCapture(e.pointerId)};for(let t of['pointerup','pointercancel','lostpointercapture'])$('#touchFire').addEventListener(t,()=>touchInput.fire=false);$('#touchUse').onclick=()=>game.interact();$('#touchWeapon').onclick=()=>{for(let n=1;n<4;n++){let w=(game.player.weapon+n)%3;if(game.player.owned[w]){game.equip(w);break}}};
function frame(t){let dt=Math.min(.05,(t-last)/1000);last=t;if(game.status==='playing'&&t>manualUntil)game.step(dt,{forward:(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0)+touchInput.forward,strafe:(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+touchInput.strafe,turn:(keys.has('ArrowRight')?1:0)-(keys.has('ArrowLeft')?1:0),sprint:keys.has('ShiftLeft')||keys.has('ShiftRight'),fire:keys.has('Space')||mouseFire||touchInput.fire});processEvents();if(game.status==='playing'||lastRenderStatus!==game.status){renderer.draw(game);lastRenderStatus=game.status}hudTimer+=dt;if(hudTimer>.1){hud();hudTimer=0}if(msgTime>0){msgTime-=dt;if(msgTime<=0)$('#message').textContent=''}requestAnimationFrame(frame)}requestAnimationFrame(frame);
const lifecycle=new AbortController();if(document.modelContext?.registerTool){let tools=[
 {name:'read_hellcat_state',description:'Read campaign status, player vitals, enemies, supplies, and the same tactical map available with M.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({...game.state(),map:game.world.map.map(r=>r.map(v=>v===2?'S':v?'#':'.').join('')),pickups:game.pickups.filter(p=>p.alive).map(({type,x,y})=>({type,x,y}))})},
 {name:'control_hellcat_campaign',description:'Start a new campaign, pause/resume, retry the current sector, or continue after reaching an exit. New and restart reset gameplay progress.',inputSchema:{type:'object',properties:{action:{enum:['new','pause','resume','restart','continue']},difficulty:{enum:['easy','normal','hard']}},required:['action'],additionalProperties:false},execute:input=>{if(!input||!['new','pause','resume','restart','continue'].includes(input.action))throw Error('Invalid campaign action.');if(input.difficulty!==undefined&&!['easy','normal','hard'].includes(input.difficulty))throw Error('Invalid difficulty.');campaign(input.action,input.difficulty);renderer.draw(game);hud();return game.state()}},
 {name:'play_hellcat_inputs',description:'Play a bounded sequence of movement, aiming, shooting and use inputs through normal game physics. Each step advances 1–180 frames at 60 fps. Can resume a paused game and pause after the sequence, using the normal pause controls. Does not teleport, grant items, or change enemy health.',inputSchema:{type:'object',properties:{resume:{type:'boolean'},pauseAfter:{type:'boolean'},steps:{type:'array',minItems:1,maxItems:40,items:{type:'object',properties:{frames:{type:'integer',minimum:1,maximum:180},forward:{type:'number',minimum:-1,maximum:1},strafe:{type:'number',minimum:-1,maximum:1},turn:{type:'number',minimum:-1,maximum:1},lookRadians:{type:'number',minimum:-6.3,maximum:6.3},fire:{type:'boolean'},sprint:{type:'boolean'},use:{type:'boolean'},weapon:{type:'integer',minimum:0,maximum:2}},required:['frames'],additionalProperties:false}}},required:['steps'],additionalProperties:false},execute:input=>{if(!input||!Array.isArray(input.steps)||!input.steps.length||input.steps.length>40)throw Error('Supply 1–40 input steps.');for(let s of input.steps){if(!s||!Number.isInteger(s.frames)||s.frames<1||s.frames>180)throw Error('Each step needs 1–180 frames.');for(let k of['forward','strafe','turn'])if(s[k]!==undefined&&(!Number.isFinite(s[k])||Math.abs(s[k])>1))throw Error('Invalid '+k);if(s.lookRadians!==undefined&&(!Number.isFinite(s.lookRadians)||Math.abs(s.lookRadians)>6.3))throw Error('Invalid look angle.');for(let k of['fire','use','sprint'])if(s[k]!==undefined&&typeof s[k]!=='boolean')throw Error('Invalid '+k);if(s.weapon!==undefined&&(!Number.isInteger(s.weapon)||s.weapon<0||s.weapon>2))throw Error('Invalid weapon.')}for(let k of ['resume','pauseAfter'])if(input[k]!==undefined&&typeof input[k]!=='boolean')throw Error('Invalid '+k);if(game.status==='paused'&&input.resume===true)campaign('resume');if(game.status!=='playing')throw Error('Resume or start the game before playing.');for(let s of input.steps){if(s.lookRadians)game.player.a=wrap(game.player.a+s.lookRadians);if(s.weapon!==undefined)game.equip(s.weapon);if(s.use)game.interact();for(let i=0;i<s.frames;i++){if(game.status!=='playing')break;game.step(1/60,s)}if(game.status!=='playing')break}manualUntil=performance.now()+150;processEvents();if(input.pauseAfter&&game.status==='playing')campaign('pause');renderer.draw(game);hud();return game.state()}}
 ];for(let tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
addEventListener('pagehide',()=>{lifecycle.abort();clearInterval(music);release();audio?.close()},{once:true});
